from datasets import load_from_disk
import numpy as np, pandas as pd
from scipy.optimize import least_squares
from sklearn.preprocessing import PolynomialFeatures
from sklearn.linear_model import Ridge, LinearRegression

df=load_from_disk('/app/data').to_pandas().copy()
df=df.sort_values(['non_vocab_parameters','vocab_size','num_characters'])
df['k']=df.groupby(['non_vocab_parameters','vocab_size']).cumcount()+1

def metrics(y,p):
 e=p-y; return np.sqrt(np.mean(e*e)),np.mean(np.abs(e)),np.max(np.abs(e))

# model functions and fitters
def fit_power(train, test, variant='U'):
    N=train.non_vocab_parameters.values; V=train.vocab_size.values; D=train.num_characters.values; y=train.unigram_normalized_loss.values
    Nt=test.non_vocab_parameters.values; Vt=test.vocab_size.values; Dt=test.num_characters.values
    def pred_arr(p,N,V,D):
        n=N/1e8; d=D/1e9; v=V/32768.0
        if variant=='U':
            return p[0]+p[1]*n**(-p[2])+p[3]*d**(-p[4])+p[5]*v**(-p[6])+p[7]*v**p[8]
        if variant=='Dcoef_smallV':
            return p[0]+p[1]*n**(-p[2])+p[3]*d**(-p[4])*(1+p[9]*v**(-p[6]))+p[5]*v**(-p[6])+p[7]*v**p[8]
        if variant=='Dcoef_bigV':
            return p[0]+p[1]*n**(-p[2])+p[3]*d**(-p[4])*(1+p[9]*v**p[8])+p[5]*v**(-p[6])+p[7]*v**p[8]
    if variant=='U':
        p0=[-5,1,.25,1,.3,.01,.5,.1,.5]; lb=[-20,-50,0,-50,0,-50,0,-50,0]; ub=[20,50,3,50,3,50,3,50,3]
    else:
        p0=[-5,1,.25,1,.3,.01,.5,.1,.5,.1]; lb=[-20,-50,0,-50,0,-50,0,-50,0,-50]; ub=[20,50,3,50,3,50,3,50,3,50]
    def res(p): return pred_arr(p,N,V,D)-y
    try:
        r=least_squares(res,p0,bounds=(lb,ub),max_nfev=20000)
        p=r.x
    except Exception as e:
        return (np.nan,np.nan,np.nan), None
    return metrics(test.unigram_normalized_loss.values,pred_arr(p,Nt,Vt,Dt)), p

def fit_poly(train,test,deg=3,ridge=0.0):
    cols=['non_vocab_parameters','vocab_size','num_characters']
    X=np.log(train[cols].values.astype(float)); Xt=np.log(test[cols].values.astype(float)); y=train.unigram_normalized_loss.values
    poly=PolynomialFeatures(deg,include_bias=True)
    Phi=poly.fit_transform(X); Phit=poly.transform(Xt)
    if ridge==0:
        lr=LinearRegression(fit_intercept=False).fit(Phi,y)
    else:
        lr=Ridge(alpha=ridge,fit_intercept=False).fit(Phi,y)
    return metrics(test.unigram_normalized_loss.values,lr.predict(Phit)), None

splits=[]
for val in sorted(df.non_vocab_parameters.unique()): splits.append((f'holdN {val:.0f}', df.non_vocab_parameters==val))
for val in sorted(df.vocab_size.unique()): splits.append((f'holdV {val:.0f}', df.vocab_size==val))
for kval in [1,2,3,5,10,15,20]: splits.append((f'holdk {kval}', df.k==kval))
# extremes train without highest groups
splits += [('hold highest N', df.non_vocab_parameters==df.non_vocab_parameters.max()),('hold lowest N', df.non_vocab_parameters==df.non_vocab_parameters.min()),('hold highest V', df.vocab_size==df.vocab_size.max()),('hold lowest V', df.vocab_size==df.vocab_size.min()),('hold high k>=16', df.k>=16),('hold low k<=3', df.k<=3)]
models=[('poly2',lambda tr,te: fit_poly(tr,te,2)),('poly3',lambda tr,te: fit_poly(tr,te,3)),('poly4ridge',lambda tr,te: fit_poly(tr,te,4,1e-6)),('U',lambda tr,te: fit_power(tr,te,'U')),('Dsmall',lambda tr,te: fit_power(tr,te,'Dcoef_smallV')),('Dbig',lambda tr,te: fit_power(tr,te,'Dcoef_bigV'))]
summary={m:[] for m,_ in models}
for name,mask in splits:
    train=df[~mask]; test=df[mask]
    if len(test)==0 or len(train)==0: continue
    print('\nSPLIT',name,'test',len(test))
    for m,fn in models:
        met,_=fn(train,test); summary[m].append(met[0])
        print(m, tuple(round(x,4) for x in met))
print('\nAVG RMSE')
for m,vals in summary.items(): print(m, np.nanmean(vals), np.nanmedian(vals), np.nanmax(vals))
